<script>
const updates=<?= json_encode(['available' => $available, 'development' => $development], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>,dialog=document.querySelector('#update-dialog'),esc=x=>String(x??'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));
function closeUpdate(){dialog.close();document.documentElement.classList.remove('modal-open');document.body.classList.remove('modal-open')}
document.querySelectorAll('[data-update]').forEach(button=>button.onclick=()=>{const [group,index]=button.dataset.update.split('-'),item=updates[group][Number(index)];document.querySelector('#update-title').textContent=item.title;document.querySelector('#update-summary').textContent=item.summary;document.querySelector('#update-details').innerHTML=item.details.map(detail=>'<li>'+esc(detail)+'</li>').join('');document.documentElement.classList.add('modal-open');document.body.classList.add('modal-open');dialog.showModal()});document.querySelector('#update-close').onclick=closeUpdate;dialog.addEventListener('close',()=>{document.documentElement.classList.remove('modal-open');document.body.classList.remove('modal-open')});
</script>
